// Feature-specific settings inside the existing Others navigation group.
const baseConfigView = configView;
const otherDefinitions = {
  Milk: {description:'Preparation, distribution and batch checks.', fields:[['Preparation variance allowance',5,'%'],['Batch review due within',30,'minutes'],['Preparation record retention',90,'days']]},
  'People / HRMS': {description:'Workforce requests and responsibility policies.',fields:[['Leave notice period',2,'days'],['Request review due within',24,'hours'],['Escalate unanswered requests after',48,'hours']]},
  Monitoring: {description:'Sensor freshness and operational alert routing.',fields:[['Reading stale after',15,'minutes'],['Repeat alert cooldown',30,'minutes'],['Escalate unacknowledged alerts after',60,'minutes']]}
};
configView = function(){
  if(current !== 'Others') return baseConfigView();
  const feature=state.otherFeature||'Milk', d=otherDefinitions[feature], key='Others / '+feature;
  $('#content').innerHTML=`<div class="feature-switch" role="group" aria-label="Others feature">${Object.keys(otherDefinitions).map((f,i)=>`<button class="${f===feature?'primary':''}" onclick="selectOtherFeature(${i})">${esc(f)}</button>`).join('')}</div><div class="two"><section class="card"><div class="cardheader"><div><h2>${esc(feature)} business rules</h2><span class="muted">${esc(d.description)}</span></div><span class="badge">Feature owned</span></div><div class="notice">Proposed example settings for design review. Each feature has its own saved policy.</div>${d.fields.map(([name,value,unit],i)=>`<label class="field"><span>${esc(name)}</span><div class="inputrow"><input id="other${i}" aria-label="${esc(name)}" type="number" min="0" step="any" value="${state.configs[key]?.[i]??value}" ${!canEdit()?'disabled':''}><span class="unit">${unit}</span></div></label>`).join('')}<button class="primary" onclick="saveOtherRules()" ${!canEdit()?'disabled':''}>Save ${esc(feature)} rules</button></section><section class="card"><h2>Keep sharing intentional</h2><p>${feature==='People / HRMS'?'People and approval lookups need their own visibility rules. Sharing a generic approval action does not share employee records.':feature==='Monitoring'?'Sensor alerts can reuse acknowledgement and escalation steps. Reading limits stay owned by Monitoring.':'Milk workflows can reuse numeric measurements, evidence and approval steps. Recipe rules stay owned by Milk.'}</p><button onclick="go('Common','Sharing')">Manage shared resources →</button><hr><h3>Workflow examples</h3><p>${feature==='Milk'?'Batch preparation → quality check → distribution or hold.':feature==='People / HRMS'?'Request details → manager decision → acknowledgement.':'Alert → physical verification → resolve or escalate.'}</p><button onclick="go('Others','SOPs')">Open Others SOP workflows →</button></section></div>`;
};
function selectOtherFeature(index){state.otherFeature=Object.keys(otherDefinitions)[index];persist();configView();}
function saveOtherRules(){if(!canEdit())return;const feature=state.otherFeature||'Milk',d=otherDefinitions[feature];const values=d.fields.map((_,i)=>Number($('#other'+i).value));if(values.some((v,i)=>!$('#other'+i).value||!Number.isFinite(v)||v<0||(d.fields[i][2]==='%'&&v>100))){toast('Enter valid non-negative values; percentages cannot exceed 100.');return;}state.configs['Others / '+feature]=values;record('Saved '+feature+' rules');toast(feature+' rules saved locally.');}
